import{_ as o,l as r,o as e,c as n,v as l,p as d,x as i,d as s,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"Kyle 在均衡框架中的位置","description":"","frontmatter":{"title":"Kyle 在均衡框架中的位置","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kyle-in-equilibrium.md","filePath":"econ/kyle-in-equilibrium.md","lastUpdated":1789023840000}'),m={name:"econ/kyle-in-equilibrium.md"};function c(h,a,u,b,B,_){const t=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="kyle-在均衡框架中的位置" tabindex="-1">Kyle 在均衡框架中的位置 <a class="header-anchor" href="#kyle-在均衡框架中的位置" aria-label="Permalink to &quot;Kyle 在均衡框架中的位置&quot;">​</a></h1><div class="epigraph"><p>知情者若能影响价格，他就不会把信号一次用尽；均衡价格冲击衡量的是战略泄漏，不是竞争性加总。</p><footer>—— Kyle, Continuous Auctions and Insider Trading, Econometrica, 1985</footer></div><p><a href="/econ/morris-shin-public-info">上一课</a>的人把价格与公告当参数，只在权重上战略。本课缺口是<strong>市场力</strong>：一个知情者选择需求量，\\(p\\) 随他的单子动。Hellwig 的连续统在此失效。不重写限价簿几何，不把 \\(\\lambda\\) 写成盘口回归——协议在 <a href="/econ/to-limit-order-book">到限价簿</a> 之后换栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞争性 REE：每人价格接受，信息经由加总泄漏。Kyle（1985）：一名风险中性知情者看见 \\(\\theta\\)，噪声交易外生，做市商（或竞争型做市端）按订单流的条件期望定价。知情者预见到自己的单子进入总流，因而选择「用多少信号」。线性均衡里 \\(p=\\mu+\\lambda y\\)，\\(y\\) 为总单，\\(\\lambda\\) 是价格冲击系数。知情者最优把泄漏摊开，使 \\(p\\) 对 \\(\\theta\\) 的回归系数停在一半（静态批量）或沿时间均匀释放（连续拍卖）。</p><p>缺口是给这套对象定位：它是战略 REE，不是 Hellwig 的竞争版，也还不是簿上的价格优先。\\(\\lambda\\) 在本栏是逆需求斜率，在量化栏才会变成可估计的冲击。本课只保留均衡陈述。</p><p><span class="marginnote">Kyle, <em>Econometrica</em> 53(6), 1985。批量版本先钉 \\(\\lambda\\)；连续时间版本说明泄漏可以是过程。做市端风险中性、有效定价，是为了把不利选择从存货里分开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三套均衡。Hellwig：价格接受、部分揭示来自供给噪声。GS：采集比例内生，仍是价格接受。Kyle：知情者人数少到必须内部化 \\(\\partial p/\\partial x\\)。噪声交易在此扮演与 \\(z\\) 类似的角色——没有它，做市端从 \\(y\\) 里完全读出 \\(\\theta\\)，知情者不敢交易，市场关闭（与 GS 的精神同构，通道换成战略）。</p><p>线性猜测再次给出闭式。揭示深度由噪声交易方差与信号精度决定：噪声越多，\\(\\lambda\\) 越低，知情者交易越猛，价格里最终仍可有一块 \\(\\theta\\)。这与「流动性越好、信息进入越快」是同一句话的两面，但流动性在本课是 \\(\\lambda^{-1}\\)，不是买卖档位。</p>',10)),(e(),d(E,null,{default:i(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20HELL%5B%22Hellwig%3A%20%E4%BB%B7%E6%A0%BC%E6%8E%A5%E5%8F%97%22%5D%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%E6%B3%84%E6%BC%8F%22%5D%0A%20%20KYLE%5B%22Kyle%3A%20%E5%86%85%E9%83%A8%E5%8C%96%20dp%2Fdx%22%5D%20--%3E%20STR%5B%22%E6%88%98%E7%95%A5%E6%B3%84%E6%BC%8F%22%5D%0A%20%20STR%20--%3E%20LAM%5B%22%CE%BB%3A%20%E9%80%86%E9%9C%80%E6%B1%82%E6%96%9C%E7%8E%87%22%5D%0A%20%20LOB%5B%22%E9%99%90%E4%BB%B7%E7%B0%BF%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20QUANT%5B%22%E6%8D%A2%E6%A0%8F%3A%20%E9%98%9F%E5%88%97%E4%B8%8E%E6%A1%A3%E4%BD%8D%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>后课不对称信息与流动性，会把 \\(\\lambda\\) 读成不利选择溢价。本课先不要价差分解，也不要存货模型。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是垄断信息的跨状态套利受到自己价格冲击的约束。多交易一单位，多赚 \\(\\theta-p\\)，也把 \\(p\\) 推向 \\(\\theta\\)，吃掉剩余。均衡卡在边际租金等于边际冲击。连续统把冲击洗成零，知情者变回价格接受者，回到 Hellwig。因此 Kyle 不是「更真实的 Hellwig」，是另一端：\\(N=1\\)（或有限）对 \\(N=\\infty\\)。</p><p>不要把噪声交易者写成行为金融的 DSSW：这里他们是外生需求，没有效用，只为了让做市端的推断有残差。行为课已经写过噪声交易者风险；本课借用噪声当残差不确定性。</p><p><span class="marginnote">多知情者、风险厌恶知情者、离散出价，会改 \\(\\lambda\\) 的公式，不改「战略泄漏」这一刀。Back、Holden–Subrahmanyam 是同一框架的延伸，本课不展开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>量化栏会估计价格冲击、买卖价差、订单流毒性。本课禁止把那些回归表写进来，也禁止画簿。\\(\\lambda\\) 不是 tick 上的弹性。下一课把战略与竞争两头收成一句理论：不对称信息本身可以定义流动性成本，无需队列。</p><p>后课默认：Kyle 是有市场力的 REE；\\(\\lambda\\) 是战略逆需求；噪声交易防止市场关闭。竞争性部分揭示是 Hellwig，不是 Kyle 的极限口头禅能替代的——极限要看 \\(N\\) 与噪声如何一起缩放。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>知情者内部化价格冲击时，泄漏是战略选择，不是竞争性加总。</li><li>\\(\\lambda\\) 是本栏的逆需求，不是盘口回归。</li><li>与 GS 同构的是「无噪声则无交易」；通道不同。</li><li>出处：Kyle, <em>Econometrica</em> 1985；对照 Hellwig 1980。</li></ul>',10))])}const f=o(m,[["render",c]]);export{y as __pageData,f as default};
